const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const sharp=require('C:/Users/myles/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const W=1536,H=1024,C={x:277,y:304,r:30};
function geometry(end){const dx=end[0]-C.x,dy=end[1]-C.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx)-Math.acos(C.r/d);return {tangent:[C.x+C.r*Math.cos(a),C.y+C.r*Math.sin(a)],length:Math.sqrt(d*d-C.r*C.r)+(a+Math.PI)*C.r};}
(async()=>{
 const masterFile=fs.readFileSync(path.join(__dirname,'1-master.png')),master=await sharp(masterFile).removeAlpha().raw().toBuffer(),records=[];
 const base=geometry([964,286]);
 // Equipment-only source mask; open carabiner hole retains the new pose beneath it.
 const mask=Buffer.from('<svg width="1536" height="1024" xmlns="http://www.w3.org/2000/svg"><path fill="white" fill-rule="evenodd" d="M964 282 L969 281 L997 283 L1000 285 L1009 285 L1014 283 L1034 283 L1039 286 L1046 285 L1058 287 L1060 296 L1056 302 L1044 301 L1040 299 L1035 300 L1015 299 L1009 295 L969 293 L964 291 Z M1016 287 L1033 288 L1034 294 L1016 294 Z"/></svg>');
 const masked=await sharp(masterFile).ensureAlpha().composite([{input:mask,blend:'dest-in'}]).png().toBuffer();
 const attachmentRaw=await sharp(masked).extract({left:964,top:280,width:97,height:24}).raw().toBuffer();
 for(let p=0;p<attachmentRaw.length;p+=4)if(attachmentRaw[p+2]-attachmentRaw[p+1]>12){const grey=Math.round((attachmentRaw[p]+attachmentRaw[p+1]+attachmentRaw[p+2])/3);attachmentRaw[p]=attachmentRaw[p+1]=attachmentRaw[p+2]=grey;};
 const attachment=await sharp(attachmentRaw,{raw:{width:97,height:24,channels:4}}).png().toBuffer();
 for(const [inputName,outputName,dx,dy] of [['2-mid-clean-cable.png','2-equipment-fixed.png',144,0],['3-full-clean-cable.png','3-equipment-fixed.png',231,16]]){
  const input=fs.readFileSync(path.join(__dirname,inputName)),out=await sharp(input).removeAlpha().raw().toBuffer();
  const copy=(x0,y0,x1,y1,shiftY=0)=>{for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const s=(y*W+x)*3,t=((y+shiftY)*W+x)*3;master.copy(out,t,s,s+3);}};
  copy(55,125,485,925);
  // Feather only the floor's rectangular copy boundary, well outside anatomy and machine solids.
  const original=await sharp(input).removeAlpha().raw().toBuffer();
  for(let y=895;y<925;y++)for(let x=55;x<485;x++){const alpha=Math.min(1,(925-y)/20,(x-55)/12,(485-x)/12);for(let c=0;c<3;c++){const p=(y*W+x)*3+c;out[p]=Math.round(out[p]*alpha+original[p]*(1-alpha));}}
  // Clear former plate and coupler with a clean horizontal source strip, preserving both guide rods.
  for(let y=580;y<628;y++)for(let x=190;x<311;x++){const s=(450*W+x)*3,t=(y*W+x)*3;master.copy(out,t,s,s+3);}
  // Remove the original free cable from the copied machine, retaining its vertical post.
  for(let y=272;y<283;y++)for(let x=309;x<485;x++){const s=(260*W+x)*3,t=(y*W+x)*3;master.copy(out,t,s,s+3);}
  const end=[964+dx,286+dy],g=geometry(end),rise=Math.round(g.length-base.length);
  // Remove the obsolete hanging cable below the raised coupler; neither guide rod is touched.
  for(let y=335;y<628;y++)for(let x=244;x<258;x++){const s=(450*W+275)*3,t=(y*W+x)*3;master.copy(out,t,s,s+3);}
  copy(190,603,311,628,-rise);copy(239,580,270,605,-rise);
  // Authorized fixed-contact source copies, restricted to shoe fronts and soles.
  for(const [x0,y0,x1,y1] of [[1080,875,1270,925],[890,900,1030,944]])for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){const p=(y*W+x)*3;if(Math.max(...master.subarray(p,p+3),...original.subarray(p,p+3))>65)master.copy(out,p,p,p+3);}
  const svg=Buffer.from(`<svg width="1536" height="1024" xmlns="http://www.w3.org/2000/svg"><path d="M247 304 L247 ${583-rise} M${g.tangent.join(' ')} L${end.join(' ')}" fill="none" stroke="#777" stroke-width="3.5"/><path d="M247 304 L247 ${583-rise} M${g.tangent.join(' ')} L${end.join(' ')}" fill="none" stroke="#c7c7c7" stroke-width="1.2"/></svg>`);
  await sharp(out,{raw:{width:W,height:H,channels:3}}).composite([{input:svg},{input:attachment,left:964+dx,top:280+dy}]).png().toFile(path.join(__dirname,outputName));
  records.push({inputName,outputName,attachmentTranslation:[dx,dy],rise,tangent:g.tangent,cableLengthError:g.length-base.length-rise,inputSha256:hash(input),outputSha256:hash(fs.readFileSync(path.join(__dirname,outputName)))});
 }
 fs.copyFileSync(path.join(__dirname,'1-master.png'),path.join(__dirname,'1-equipment-fixed.png'));
 fs.writeFileSync(path.join(__dirname,'equipment-repair-provenance.json'),JSON.stringify({authorization:'User approved code-based weights, attachments and measured cable paths for Pallof and all remaining sets.',method:'Frozen machine and resting plates restored; selected plate and coupler translated rigidly. Equipment-only master connector mask translated, leaving carabiner hole transparent. Analytic free-cable tangent overlays generated anatomy naturally. No anatomy redrawn or transformed. Shoe forefoot and sole source copies use existing fixed-contact authorization.',masterSha256:hash(masterFile),records},null,2));console.log(records);
})();

const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const sharp=require('C:/Users/myles/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
(async()=>{
 const files=['1-equipment-fixed.png','2-equipment-fixed.png','3-equipment-fixed.png'],rows=[];
 const scans=[{name:'left shoe upper',y:880,x0:890,x1:1030,t:120},{name:'right shoe upper',y:880,x0:1090,x1:1260,t:120},{name:'left forefoot',y:910,x0:890,x1:1030,t:120},{name:'right forefoot',y:910,x0:1090,x1:1260,t:120},{name:'left planted sole',y:928,x0:890,x1:1030,t:120},{name:'right planted sole',y:916,x0:1090,x1:1260,t:120}];
 scans.push({name:'machine base',y:870,x0:60,x1:485,t:70},{name:'resting stack',y:700,x0:190,x1:320,t:25});
 for(const file of files){const bytes=fs.readFileSync(path.join(__dirname,file));const{data,info}=await sharp(bytes).removeAlpha().raw().toBuffer({resolveWithObject:true});const measures=scans.map(s=>{const xs=[];for(let x=s.x0;x<s.x1;x++){const p=(s.y*info.width+x)*3;if(Math.min(...data.subarray(p,p+3))>s.t)xs.push(x);}return {name:s.name,y:s.y,left:xs[0],right:xs.at(-1),width:xs.at(-1)-xs[0]+1};});rows.push({file,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),measures});}
 for(const row of rows)for(let i=0;i<row.measures.length;i++){const a=row.measures[i],b=rows[0].measures[i];a.leftDelta=a.left-b.left;a.rightDelta=a.right-b.right;a.widthPercent=100*(a.width/b.width-1);}
 fs.writeFileSync(path.join(__dirname,'contact-measurements.json'),JSON.stringify(rows,null,2)+'\n');console.log(rows.map(r=>({file:r.file,measures:r.measures})));
})();
